struct SnapshotCodec;

struct Snapshot
{
    using WireCodec = SnapshotCodec;

    u32                   tick = 0U;
    WireList<EntityCodec> entities;
};

struct SnapshotCodec
{
    using Value = Snapshot;
    static constexpr u16 kSchemaMinor = kMinor;
    static constexpr u32 kMessageId = 1U;
    static constexpr u32 kMinBytes = 2U; // at the first minor revision
    static constexpr u32 kMaxBytes = 1278U; // at the current minor revision
    static constexpr bool kLossy = true; // a decoded value may re-encode to other bits

    // The storage its lists decode into, from the value a decode starts over.
    static void keep(Value& fresh, const Value& old) noexcept
    {
        fresh.entities.into(old.entities.storage());
    }

    [[nodiscard]] static WireError encode(const Value& value, cont::BitWriter& w,
                                                 [[maybe_unused]] u16 minor) noexcept
    {
        wire_put_varuint(w, value.tick, 7U);
        if (const WireError error = wire_keys_ascend(value.entities, WireKeyOf<&Entity::id>{});
            error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = wire_put_list(w, value.entities, 0U, 64U, 7U, minor);
            error != WireError::Ok)
        {
            return error;
        }
        return WireError::Ok;
    }

    [[nodiscard]] static u64 end([[maybe_unused]] const Value& value, [[maybe_unused]] u16 minor,
                                 u64 position) noexcept
    {
        position += wire_varuint_bits(value.tick, 7U);
        position = wire_list_end(value.entities, 7U, minor, position);
        return position;
    }

    [[nodiscard]] static WireError decode(cont::BitReader& r, [[maybe_unused]] u16 writer_minor,
                                                 Value& value) noexcept
    {
        value = wire_fresh<SnapshotCodec>(value);
        if (const WireError error = wire_take_varuint_as(r, 7U, 4294967295ULL, value.tick);
            error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error =
                wire_take_list(r, 0U, 64U, 7U, writer_minor, value.entities, WireKeyOf<&Entity::id>{});
            error != WireError::Ok)
        {
            return error;
        }
        return WireError::Ok;
    }

    [[nodiscard]] static bool same(const Value& a, const Value& b) noexcept
    {
        return wire_same(a.tick, b.tick) &&
               wire_same_list(a.entities, b.entities);
    }
};

