struct ChatCodec;

struct Chat
{
    using WireCodec = ChatCodec;

    u16                             sender = static_cast<u16>(0ULL);
    Room                            room = Room::All;
    std::string_view                text;
    WireList<ChatMentionsItemCodec> mentions;
};

struct ChatCodec
{
    using Value = Chat;
    static constexpr u16 kSchemaMinor = kMinor;
    static constexpr u32 kMessageId = 3U;
    static constexpr u32 kMinBytes = 3U; // at the first minor revision
    static constexpr u32 kMaxBytes = 214U; // at the current minor revision
    static constexpr bool kLossy = false; // a decoded value may re-encode to other bits

    // The storage its lists decode into, from the value a decode starts over.
    static void keep(Value& fresh, const Value& old) noexcept
    {
        fresh.mentions.into(old.mentions.storage());
    }

    [[nodiscard]] static WireError encode(const Value& value, cont::BitWriter& w,
                                                 [[maybe_unused]] u16 minor) noexcept
    {
        if (!wire_range_holds<u16>(value.sender, static_cast<u16>(0ULL), 1023ULL))
        {
            return WireError::OutOfRange;
        }
        wire_put_range<u16>(w, value.sender, static_cast<u16>(0ULL), 10U);
        if (!enum_known(value.room, minor))
        {
            return enum_known(value.room, kMinor) ? WireError::NotInRevision : WireError::UnknownValue;
        }
        w.put(static_cast<u64>(value.room), 2U);
        if (value.text.size() > 200U)
        {
            return WireError::OutOfRange;
        }
        if (!wire_text_valid(wire_text_bytes(value.text)))
        {
            return WireError::BadText;
        }
        wire_put_bytes(w, wire_text_bytes(value.text), 0U, 8U);
        if (const WireError error = wire_put_list(w, value.mentions, 0U, 8U, 4U, minor);
            error != WireError::Ok)
        {
            return error;
        }
        return WireError::Ok;
    }

    [[nodiscard]] static u64 end([[maybe_unused]] const Value& value, [[maybe_unused]] u16 minor,
                                 u64 position) noexcept
    {
        position += 10U;
        position += 2U;
        position = wire_bytes_end(position, 8U, value.text.size());
        position = wire_list_end(value.mentions, 4U, minor, position);
        return position;
    }

    [[nodiscard]] static WireError decode(cont::BitReader& r, [[maybe_unused]] u16 writer_minor,
                                                 Value& value) noexcept
    {
        value = wire_fresh<ChatCodec>(value);
        if (const WireError error = wire_take_range<u16>(r, static_cast<u16>(0ULL), 1023ULL, 10U, value.sender);
            error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = wire_take_uint(r, 2U, value.room); error != WireError::Ok)
        {
            return error;
        }
        if (writer_minor <= kMinor && !enum_known(value.room, writer_minor))
        {
            return WireError::UnknownValue;
        }
        if (const WireError error = wire_take_text(r, 200U, 8U, value.text); error != WireError::Ok)
        {
            return error;
        }
        if (const WireError error = wire_take_list(r, 0U, 8U, 4U, writer_minor, value.mentions);
            error != WireError::Ok)
        {
            return error;
        }
        return WireError::Ok;
    }

    [[nodiscard]] static bool same(const Value& a, const Value& b) noexcept
    {
        return wire_same(a.sender, b.sender) &&
               wire_same(a.room, b.room) &&
               a.text == b.text &&
               wire_same_list(a.mentions, b.mentions);
    }
};

